using System.Text.RegularExpressions;using Dip.Application.Abstractions.Persistence;using Dip.Domain.Enums;
namespace Dip.Application.Features.Intelligence;
public sealed class RootCauseIntelligenceService
{
    readonly IEvidenceRepository _evidence;public RootCauseIntelligenceService(IEvidenceRepository evidence){_evidence=evidence;}
    public async Task<RootCauseResult> AnalyzeAsync(RootCauseRequest r,CancellationToken ct){var corpus=string.Join('\n',new[]{r.FindingText,r.StackTrace,r.DiffText,string.Join('\n',r.LogLines)});if(string.IsNullOrWhiteSpace(corpus))return new(Array.Empty<RootCauseCandidate>(),"Insufficient Evidence");var candidates=new List<RootCauseCandidate>();void Add(string cause,decimal c,string marker,string action){var hits=Regex.Matches(corpus,marker,RegexOptions.IgnoreCase).Count;if(hits>0)candidates.Add(new(cause,Math.Min(95,c+hits*3),new[]{ $"Matched evidence pattern: {marker}", $"Observed {hits} time(s) in supplied evidence."},r.IncludeSuggestedAction?action:null));}
        Add("Object lifetime / memory ownership defect",72,"use-after-free|access violation|double free|heap corruption","Review ownership and lifetime around the top application frame; reproduce under sanitizer.");
        Add("Out-of-bounds memory access",75,"buffer overflow|out.?of.?range|IndexOutOfRange","Validate bounds and container sizes around the first failing application frame.");
        Add("Null or missing reference",70,"NullReference|NoneType|null pointer|missing reference","Trace the value back to its producer and add a precondition at the boundary.");
        Add("Concurrency / wait-cycle defect",65,"deadlock|timeout|hang|TaskCanceled|lock contention","Capture thread stacks during the hang and inspect lock ordering / awaited dependencies.");
        Add("Resource or memory pressure",68,"out of memory|OOM|memory growth|leak|allocation","Compare allocation growth and target hardware memory budget; inspect retained resources.");
        var recent=await _evidence.ListForProjectAsync(r.ProjectId,DateTimeOffset.UtcNow.AddDays(-120),ct);var similar=recent.Where(x=>x.SubjectKey==r.SubjectKey&&x.Outcome==EvidenceOutcome.Failed).Take(5).ToArray();if(similar.Length>0)candidates.Add(new("Recurring failure in the same subsystem",60+Math.Min(25,similar.Length*4),similar.Select(x=>$"Prior evidence: {x.Title} ({x.ObservedAtUtc:u})").ToArray(),r.IncludeSuggestedAction?"Compare the current fingerprint/stack with prior incidents before changing unrelated code.":null));return new(candidates.OrderByDescending(x=>x.ConfidencePercent).Take(5).ToArray(),candidates.Count>0?"Evidence Grounded":"Insufficient Evidence");}
}
